CREATE TABLE entregas(id TEXT PRIMARY KEY,trabajo_id INTEGER NOT NULL REFERENCES trabajos(id),numero INTEGER NOT NULL,creado TEXT NOT NULL,operador TEXT NOT NULL,estado TEXT NOT NULL,ruta TEXT NOT NULL,manifest_hash TEXT,inventario_hash TEXT,manifest TEXT,UNIQUE(trabajo_id,numero));
CREATE TABLE entrega_items(id INTEGER PRIMARY KEY,entrega_id TEXT NOT NULL REFERENCES entregas(id),documento_id TEXT NOT NULL REFERENCES documentos_logicos(id),version_id TEXT NOT NULL REFERENCES versiones_archivo(id),archivo_id INTEGER NOT NULL REFERENCES archivos_tiff(id),nombre TEXT NOT NULL,nombre_origen TEXT,codigo TEXT NOT NULL,carpeta TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,paginas INTEGER NOT NULL,modalidad TEXT NOT NULL,ruta TEXT NOT NULL,UNIQUE(entrega_id,documento_id),UNIQUE(entrega_id,ruta));
CREATE TABLE validaciones(id TEXT PRIMARY KEY,trabajo_id INTEGER NOT NULL REFERENCES trabajos(id),entrega_id TEXT REFERENCES entregas(id),fecha TEXT NOT NULL,operador TEXT NOT NULL,resultado TEXT NOT NULL,vigente INTEGER NOT NULL DEFAULT 1,huella_base TEXT NOT NULL,informe TEXT NOT NULL);
CREATE TABLE sesiones_revision(id TEXT PRIMARY KEY,entrega_id TEXT NOT NULL REFERENCES entregas(id),revisor TEXT NOT NULL,inicio TEXT NOT NULL,fin TEXT,estado TEXT NOT NULL DEFAULT 'En revisión');
CREATE TABLE observaciones_revision(id INTEGER PRIMARY KEY,sesion_id TEXT NOT NULL REFERENCES sesiones_revision(id),entrega_detectada TEXT NOT NULL REFERENCES entregas(id),documento_id TEXT REFERENCES documentos_logicos(id),version_id TEXT REFERENCES versiones_archivo(id),pagina INTEGER,ubicacion_fisica TEXT NOT NULL DEFAULT '',tipo TEXT NOT NULL,descripcion TEXT NOT NULL,evidencia TEXT NOT NULL DEFAULT '',creador TEXT NOT NULL,creado TEXT NOT NULL,responsable TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Abierta',respuesta TEXT NOT NULL DEFAULT '',entrega_resuelta TEXT REFERENCES entregas(id),bloqueante INTEGER NOT NULL DEFAULT 1);
CREATE TABLE observacion_historial(id INTEGER PRIMARY KEY,observacion_id INTEGER NOT NULL REFERENCES observaciones_revision(id),fecha TEXT NOT NULL,operador TEXT NOT NULL,estado TEXT NOT NULL,respuesta TEXT NOT NULL,entrega_id TEXT REFERENCES entregas(id));
CREATE TABLE importaciones_legado(id TEXT PRIMARY KEY,trabajo_id INTEGER NOT NULL REFERENCES trabajos(id),origen TEXT NOT NULL,modo TEXT NOT NULL,fecha TEXT NOT NULL,operador TEXT NOT NULL,estado TEXT NOT NULL,informe TEXT NOT NULL);
CREATE TRIGGER entrega_items_inmutables BEFORE UPDATE ON entrega_items BEGIN SELECT RAISE(ABORT,'Entrega inmutable.'); END;
CREATE TRIGGER entrega_items_no_borrar BEFORE DELETE ON entrega_items BEGIN SELECT RAISE(ABORT,'Entrega inmutable.'); END;
CREATE TRIGGER entrega_manifest_inmutable BEFORE UPDATE OF manifest,manifest_hash,inventario_hash ON entregas WHEN OLD.manifest IS NOT NULL BEGIN SELECT RAISE(ABORT,'Manifest inmutable.'); END;
CREATE TRIGGER entrega_no_borrar BEFORE DELETE ON entregas BEGIN SELECT RAISE(ABORT,'No borrar una entrega histórica.'); END;
CREATE INDEX idx_entregas_trabajo ON entregas(trabajo_id,numero);
CREATE INDEX idx_validacion_ciclo ON validaciones(trabajo_id,fecha);
CREATE INDEX idx_observacion_entrega ON observaciones_revision(entrega_detectada,estado);
